def semver_sort(versions):
    def parse(v):
        core_and_meta = v.split('+', 1)
        core = core_and_meta[0]
        if '-' in core:
            idx = core.index('-')
            main = core[:idx]
            prerelease = core[idx+1:]
        else:
            main = core
            prerelease = None
        major, minor, patch = (int(x) for x in main.split('.'))
        if prerelease is not None:
            ids = prerelease.split('.')
            id_keys = []
            for ident in ids:
                if ident.isdigit():
                    id_keys.append((0, int(ident)))
                else:
                    id_keys.append((1, ident))
            has_pre_flag = 0
        else:
            id_keys = []
            has_pre_flag = 1
        return (major, minor, patch, has_pre_flag, id_keys)

    return sorted(versions, key=parse)

